namespace sv_bd84b8e7a4ee4602a73565a384f96086.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Fires an event when the selection changes so all subscribed components can update.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<Warehouse> AvailableWarehouses =
    [
        new("wh-1", "Warehouse A"),
        new("wh-2", "Warehouse B"),
        new("wh-3", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public sealed record Warehouse(string Id, string Name);

namespace sv_bd84b8e7a4ee4602a73565a384f96086.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts for a warehouse.
/// Maintains the latest count and notifies all subscribers when new data arrives.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result (0–15).
        int count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Refreshes the alert count for the given warehouse and notifies all subscribers.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

