@using sv_bd84b8e7a4ee4602a73565a384f96086.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_bd84b8e7a4ee4602a73565a384f96086.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="badge @BadgeClass">@AlertService.CurrentAlertCount</span>

@code {
    private string BadgeClass => AlertService.CurrentAlertCount > 0
        ? "bg-danger"
        : "bg-secondary";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

@page "/dashboard"
@using sv_bd84b8e7a4ee4602a73565a384f96086.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            <span class="fs-2 fw-bold @(AlertService.CurrentAlertCount > 0 ? "text-danger" : "text-success")">
                @AlertService.CurrentAlertCount
            </span>
            <span class="text-muted ms-2">items below minimum levels</span>
        </p>
        <p class="text-muted small">Auto-refreshes every 10 seconds while this page is open.</p>
    </div>
</div>

@code {
    private CancellationTokenSource? _pollCts;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling when the dashboard becomes visible.
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
        }
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse immediately.
        StopPolling();
        InvokeAsync(async () =>
        {
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
            StateHasChanged();
        });
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void StartPolling()
    {
        _pollCts = new CancellationTokenSource();
        var token = _pollCts.Token;

        _ = Task.Run(async () =>
        {
            while (!token.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(10), token);
                if (token.IsCancellationRequested) break;
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
                });
            }
        }, token);
    }

    private void StopPolling()
    {
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        _pollCts = null;
    }

